@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
.ui-root { --ui-primary: #E8702A; --ui-primary-text: #111111; --ui-bg: #FFF9F4; --ui-surface: #FFFFFF; --ui-surface-2: color-mix(in srgb, #2B2118 6%, #FFFFFF); --ui-text: #2B2118; --ui-muted: #7A6B5D; --ui-border: color-mix(in srgb, #2B2118 14%, #FFF9F4); --ui-success: #2E8B57; --ui-warning: #d97706; --ui-danger: #C8382E; --ui-info: #2563eb; --ui-radius: 12px; --ui-radius-sm: calc(12px / 2); --ui-space: 4px; --ui-shadow: 0 1px 2px rgb(16 24 40 / 0.06), 0 4px 12px rgb(16 24 40 / 0.06); --ui-font: 'Inter', system-ui, sans-serif; --ui-font-heading: 'Inter', system-ui, sans-serif; font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); background: var(--ui-bg); }
