/* Page header */
.ui-root .ui-page { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 8); max-width: 1200px; margin: 0 auto; padding: calc(var(--ui-space) * 8) calc(var(--ui-space) * 6); color: var(--ui-text); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; }
.ui-root .ui-page-header { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: calc(var(--ui-space) * 4); padding: calc(var(--ui-space) * 6); background:
