.ui-root .ui-link { color: var(--ui-text); font-family: var(--ui-font); font-size: 15px; font-weight: 600; text-decoration: underline; text-decoration-color: var(--ui-primary); text-decoration-thickness: 2px; text-underline-offset: 3px; transition: text-decoration-color 150ms ease; }
