.ui-root .ui-timeline-time { display: inline-block; margin: 0 0 calc(var(--ui-space) * 1); padding: calc(var(--ui-space) * 0.5) calc(var(--ui-space) * 2.5); border-radius: 999px; background: var(--ui-surface-2); border: 1px solid var(--ui-border); font-family: var(--ui-font); font-size: 14px; font-weight: 500; line-height: 1.4; color: var(--ui-muted); white-space: nowrap; }
.ui-root .ui-timeline-item:last-child .ui-timeline-time { color: var(--ui-success); border-color: var(--ui-success); background: var(--ui-surface); }

/* Messages and empty states */
.ui-root .ui-empty { display: flex; flex-direction: column; align-items: center; text-align: center; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 12) calc(var(--ui-space) * 6); background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); }
