.ui-root .ui-alert { position: relative; display: flex; align-items: flex-start; gap: calc(var(--ui-space) * 3); padding: calc(var(--ui-space) * 3) calc(var(--ui-space) * 4); background: var(--ui-surface); color: var(--ui-text); font-size: 14px; line-height: 1.5; border: 1px solid var(--ui-border); border-left: 4px solid var(--ui-primary); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); }
