.ui-root .ui-alert-info { border-left-color: var(--ui-info); background: color-mix(in srgb, var(--ui-info) 8%, var(--ui-surface)); }
.ui-root .ui-alert-info::before { background: var(--ui-info); }
.ui-root .ui-alert-success { border-left-color: var(--ui-success); background: color-mix(in srgb, var(--ui-success) 8%, var(--ui-surface)); }
.ui-root .ui-alert-success::before { background: var(--ui-success); }
.ui-root .ui-alert-warning { border-left-color: var(--ui-warning); background: color-mix(in srgb, var(--ui-warning) 10%, var(--ui-surface)); }
.ui-root .ui-alert-warning::before { background: var(--ui-warning); }
.ui-root .ui-alert-danger { border-left-color: var(--ui-danger); background: color-mix(in srgb, var(--ui-danger) 8%, var(--ui-surface)); }
